/* two-line row, laid out like PAZARLAMA / ERKEN ERİŞİM'DE: label on the top line, the 5-step bar where the sub-label sits.
   Everything stays inside x 56..167 (BADGE_RIGHT 16 from the 183 px rail). */
.rr.two { display: block; padding: 0; }
.rr.two .rr-ic { position: absolute; left: 20px; top: 12px; }
.rr.two .lab { position: absolute; left: 56px; top: 7px; font-size: 16px; line-height: 16px; color: var(--ink-3); white-space: nowrap; }
.rr.two .cnt { position: absolute; right: 16px; top: 7px; font-size: 16px; line-height: 16px; color: var(--ink-3); white-space: nowrap; }
.segs { position: absolute; left: 56px; right: 16px; top: 31px; height: 4px; display: flex; gap: 3px; }
.segs i { position: relative; flex: 1; border-radius: 1px; background: var(--line-2); overflow: hidden; }
.segs i b { position: absolute; left: 0; top: 0; bottom: 0; background: var(--ink-3); }
.rr.is-active .lab { color: var(--ink-1); }
.rr.is-active .cnt { color: var(--ink-2); }
.rr.is-active .segs i b { background: var(--ink-2); }

/* ---------------------------------------------------------------- tooltip (TooltipPanel, one line) */
.tip { position: absolute; display: flex; align-items: baseline; padding: 12px; background: var(--s0);
  border: 1px solid var(--line-2); border-radius: 4px; box-shadow: var(--shadow-tip); white-space: nowrap; font-size: 15px; line-height: 21px; }
.tip-t { color: var(--ink-1); }
.tip-b { color: var(--ink-3); }

/* ---------------------------------------------------------------- the goals drawer, docked to the rail (A's place and width, B's order) */
.gp { position: absolute; left: 184px; bottom: 52px; width: 392px; background: var(--s3); border: 1px solid var(--line-2); border-left: 0;
  border-radius: 0 6px 6px 0; box-shadow: var(--shadow-float), 24px 0 48px -12px rgba(10, 8, 6, 0.5); overflow: hidden; }
.gp-hd { height: 56px; display: flex; align-items: center; gap: 12px; padding: 0 8px 0 20px; background: var(--s4); border-bottom: 1px solid var(--line-1); }
.gp-hd .t { flex: 1; font-size: 22px; line-height: 30px; color: var(--ink-1); }
.gp-hd .ic-t { width: 20px; height: 20px; color: var(--ink-2); }
.x-btn { width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; border: 1px solid transparent; border-radius: 4px; color: var(--ink-3); }

/* list head: who set the goals and how far along */
.who { display: flex; align-items: center; gap: 12px; padding: 16px 20px; }
.av { width: 40px; height: 40px; border-radius: 50%; flex: none; box-shadow: 0 0 0 1px var(--line-3); background: radial-gradient(circle at 50% 40%, var(--portrait-lit), var(--portrait-edge)); overflow: hidden; }
.av img { width: 40px; height: 40px; display: block; }
.who .name { flex: 1; font-size: 18px; line-height: 24px; color: var(--ink-1); white-space: nowrap; }
.who .count { font-size: 16px; line-height: 22px; color: var(--ink-2); }
.sep { height: 1px; margin: 0 20px; background: var(--line-1); }

/* the current step, on top and large */
.hero { display: flex; flex-direction: column; gap: 12px; padding: 16px 20px; }
.h-row { display: flex; align-items: center; gap: 12px; }
.h-title { flex: 1; font-size: 22px; line-height: 30px; color: var(--ink-1); white-space: nowrap; }
.btn { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; box-sizing: border-box; flex: none;
  border: 1px solid var(--line-2); border-radius: 4px; color: var(--ink-2); white-space: nowrap;
  font-weight: 650; font-variation-settings: "wght" 650, "wdth" 62; font-size: 16px; line-height: 22px; }
.btn svg { width: 16px; height: 16px; color: var(--ink-3); }
.h-bar { display: flex; align-items: center; gap: 12px; }
.bar { position: relative; flex: 1; height: 8px; border-radius: 2px; background: var(--bar-track); overflow: hidden; }
.bar i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 2px; background: var(--ink-2); }
.fig { font-size: 15px; line-height: 21px; color: var(--ink-3); white-space: nowrap; }
.fig b { font-weight: 650; font-variation-settings: "wght" 650, "wdth" 100; color: var(--ink-1); }

/* the ladder: one thin line through the step marks (x 27, the centre of the 16 px marks at 20..36) */
.ladder { position: relative; padding: 4px 20px 16px; }
.ladder::before { content: ""; position: absolute; left: 27px; top: 20px; bottom: 32px; width: 1px; background: var(--line-2); }
.ls { position: relative; height: 32px; display: flex; align-items: center; gap: 12px; font-size: 15px; line-height: 21px; color: var(--ink-3); white-space: nowrap; }
.mk { position: relative; z-index: 1; width: 16px; height: 16px; flex: none; box-sizing: border-box; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; background: var(--s3); }
/* pos-tag-bg / pos-tag-line flattened onto surface-3 so the line does not show through */
.ls.done .mk { background: #243124; border: 1px solid #3A7F4E; color: var(--pos); }
.ls.done .mk svg { width: 12px; height: 12px; }
.ls.now { color: var(--ink-1); }
.ls.now .mk { border: 2px solid var(--ink-2); }

/* the next list: dimmed and locked */
.next { position: relative; padding: 12px 20px 14px; background: var(--s2); border-top: 1px solid var(--line-1); }
.next::before { content: ""; position: absolute; left: 27px; top: 54px; height: 28px; width: 1px; background: var(--line-1); }
.n-hd { height: 28px; display: flex; align-items: center; gap: 12px; }
.n-hd svg { width: 16px; height: 16px; color: var(--ink-4); }
.n-hd .t { flex: 1; font-size: 16px; line-height: 22px; color: var(--ink-4); }
.n-hd .c { font-size: 15px; line-height: 21px; color: var(--ink-4); }
.next .ls { height: 28px; color: var(--ink-off); }
.next .ls .mk { background: var(--s2); border: 1px solid var(--line-3); }

/* states, switched by the URL hash: #closed, #hover, #open */
.only-open, .only-hover { display: none; }
body.s-open .only-open { display: block; }
body.s-hover .only-hover { display: flex; }

